    float tripletFactorR = aw_s->tripletFactorR;
    bool flipA = aw_s->flipA;
    bool flipB = aw_s->flipB;
    bool flop = aw_s->flop;
    int count = aw_s->count;
    uint32_t fpdL = aw_s->fpdL;
