static void aw_Air_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_Air_fast_t *aw_s = (aw_Air_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float airPrevAL = aw_s->airPrevAL;
    float airEvenAL = aw_s->airEvenAL;
    float airOddAL = aw_s->airOddAL;
    float airFactorAL = aw_s->airFactorAL;
    float airPrevBL = aw_s->airPrevBL;
    float airEvenBL = aw_s->airEvenBL;
    float airOddBL = aw_s->airOddBL;
    float airFactorBL = aw_s->airFactorBL;
    float airPrevCL = aw_s->airPrevCL;
    float airEvenCL = aw_s->airEvenCL;
    float airOddCL = aw_s->airOddCL;
    float airFactorCL = aw_s->airFactorCL;
    float tripletPrevL = aw_s->tripletPrevL;
    float tripletMidL = aw_s->tripletMidL;
    float tripletAL = aw_s->tripletAL;
    float tripletBL = aw_s->tripletBL;
    float tripletCL = aw_s->tripletCL;
    float tripletFactorL = aw_s->tripletFactorL;
    float airPrevAR = aw_s->airPrevAR;
    float airEvenAR = aw_s->airEvenAR;
    float airOddAR = aw_s->airOddAR;
    float airFactorAR = aw_s->airFactorAR;
    float airPrevBR = aw_s->airPrevBR;
    float airEvenBR = aw_s->airEvenBR;
    float airOddBR = aw_s->airOddBR;
    float airFactorBR = aw_s->airFactorBR;
    float airPrevCR = aw_s->airPrevCR;
    float airEvenCR = aw_s->airEvenCR;
    float airOddCR = aw_s->airOddCR;
    float airFactorCR = aw_s->airFactorCR;
    float tripletPrevR = aw_s->tripletPrevR;
    float tripletMidR = aw_s->tripletMidR;
    float tripletAR = aw_s->tripletAR;
    float tripletBR = aw_s->tripletBR;
    float tripletCR = aw_s->tripletCR;
    float tripletFactorR = aw_s->tripletFactorR;
    bool flipA = aw_s->flipA;
    bool flipB = aw_s->flipB;
    bool flop = aw_s->flop;
    int count = aw_s->count;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    float E = aw_s->E;
    float F = aw_s->F;
    {

	double hiIntensity = -pow(((A*2.0)-1.0),3)*2;
	double tripletintensity = -pow(((B*2.0)-1.0),3);
	double airIntensity = -pow(((C*2.0)-1.0),3)/2;
	double filterQ = 2.1-D;
	double output = E;
	double wet = F;
	double dry = 1.0-wet;
	

	float inputSampleL;
	float inputSampleR;
	float drySampleL;
	float drySampleR;
	float correctionL;
	float correctionR;
    
    const float aw_f_hiIntensity = (float)hiIntensity;
	const float aw_f_tripletintensity = (float)tripletintensity;
	const float aw_f_airIntensity = (float)airIntensity;
	const float aw_f_filterQ = (float)filterQ;
	const float aw_f_output = (float)output;
	const float aw_f_wet = (float)wet;
	const float aw_f_dry = (float)dry;
	const float aw_inv0 = 1.0f / ( aw_f_filterQ);
	const float aw_inv1 = 1.0f / (256.0f);
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		inputSampleL = aw_inL;
		inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		drySampleL = inputSampleL;
		drySampleR = inputSampleR;
		
		correctionL = 0.0f;
		correctionR = 0.0f;  //from here on down, please add L and R to the code
		
		if (count < 1 || count > 3) count = 1;
		tripletFactorL = tripletPrevL - inputSampleL;
		tripletFactorR = tripletPrevR - inputSampleR;
		switch (count)
		{
			case 1:
				tripletAL += tripletFactorL;
				tripletCL -= tripletFactorL;
				tripletFactorL = tripletAL * aw_f_tripletintensity;
				tripletPrevL = tripletMidL;
				tripletMidL = inputSampleL;
				
				tripletAR += tripletFactorR;
				tripletCR -= tripletFactorR;
				tripletFactorR = tripletAR * aw_f_tripletintensity;
				tripletPrevR = tripletMidR;
				tripletMidR = inputSampleR;
				break;
			case 2:
				tripletBL += tripletFactorL;
				tripletAL -= tripletFactorL;
				tripletFactorL = tripletBL * aw_f_tripletintensity;
				tripletPrevL = tripletMidL;
				tripletMidL = inputSampleL;
				
				tripletBR += tripletFactorR;
				tripletAR -= tripletFactorR;
				tripletFactorR = tripletBR * aw_f_tripletintensity;
				tripletPrevR = tripletMidR;
				tripletMidR = inputSampleR;
				break;
			case 3:
				tripletCL += tripletFactorL;
				tripletBL -= tripletFactorL;
				tripletFactorL = tripletCL * aw_f_tripletintensity;
				tripletPrevL = tripletMidL;
				tripletMidL = inputSampleL;
				
				tripletCR += tripletFactorR;
				tripletBR -= tripletFactorR;
				tripletFactorR = tripletCR * aw_f_tripletintensity;
				tripletPrevR = tripletMidR;
				tripletMidR = inputSampleR;
				break;
		}
		tripletAL *= aw_inv0;
		tripletBL *= aw_inv0;
		tripletCL *= aw_inv0;
		correctionL = correctionL + tripletFactorL;

		tripletAR *= aw_inv0;
		tripletBR *= aw_inv0;
		tripletCR *= aw_inv0;
		correctionR = correctionR + tripletFactorR;
		
		count++;
		//finished Triplet section- 15K
		
		if (flop)
		{
			airFactorAL = airPrevAL - inputSampleL;
			airFactorAR = airPrevAR - inputSampleR;
			if (flipA)
			{
				airEvenAL += airFactorAL;
				airOddAL -= airFactorAL;
				airFactorAL = airEvenAL * aw_f_airIntensity;

				airEvenAR += airFactorAR;
				airOddAR -= airFactorAR;
				airFactorAR = airEvenAR * aw_f_airIntensity;
			}
			else
			{
				airOddAL += airFactorAL;
				airEvenAL -= airFactorAL;
				airFactorAL = airOddAL * aw_f_airIntensity;

				airOddAR += airFactorAR;
				airEvenAR -= airFactorAR;
				airFactorAR = airOddAR * aw_f_airIntensity;
			}
			airOddAL = (airOddAL - ((airOddAL - airEvenAL)* aw_inv1)) * aw_inv0;
			airEvenAL = (airEvenAL - ((airEvenAL - airOddAL)* aw_inv1)) * aw_inv0;
			airPrevAL = inputSampleL;
			correctionL = correctionL + airFactorAL;

			airOddAR = (airOddAR - ((airOddAR - airEvenAR)* aw_inv1)) * aw_inv0;
			airEvenAR = (airEvenAR - ((airEvenAR - airOddAR)* aw_inv1)) * aw_inv0;
			airPrevAR = inputSampleR;
			correctionR = correctionR + airFactorAR;

			flipA = !flipA;
		}
		else
		{
			airFactorBL = airPrevBL - inputSampleL;
			airFactorBR = airPrevBR - inputSampleR;
			if (flipB)
			{
				airEvenBL += airFactorBL;
				airOddBL -= airFactorBL;
				airFactorBL = airEvenBL * aw_f_airIntensity;

				airEvenBR += airFactorBR;
				airOddBR -= airFactorBR;
				airFactorBR = airEvenBR * aw_f_airIntensity;
			}
			else
			{
				airOddBL += airFactorBL;
				airEvenBL -= airFactorBL;
				airFactorBL = airOddBL * aw_f_airIntensity;

				airOddBR += airFactorBR;
				airEvenBR -= airFactorBR;
				airFactorBR = airOddBR * aw_f_airIntensity;
			}
			airOddBL = (airOddBL - ((airOddBL - airEvenBL)* aw_inv1)) * aw_inv0;
			airEvenBL = (airEvenBL - ((airEvenBL - airOddBL)* aw_inv1)) * aw_inv0;
			airPrevBL = inputSampleL;
			correctionL = correctionL + airFactorBL;

			airOddBR = (airOddBR - ((airOddBR - airEvenBR)* aw_inv1)) * aw_inv0;
			airEvenBR = (airEvenBR - ((airEvenBR - airOddBR)* aw_inv1)) * aw_inv0;
			airPrevBR = inputSampleR;
			correctionR = correctionR + airFactorBR;

			flipB = !flipB;
		}
		//11K one
		airFactorCL = airPrevCL - inputSampleL;
		airFactorCR = airPrevCR - inputSampleR;
		if (flop)
		{
			airEvenCL += airFactorCL;
			airOddCL -= airFactorCL;
			airFactorCL = airEvenCL * aw_f_hiIntensity;

			airEvenCR += airFactorCR;
			airOddCR -= airFactorCR;
			airFactorCR = airEvenCR * aw_f_hiIntensity;
		}
		else
		{
			airOddCL += airFactorCL;
			airEvenCL -= airFactorCL;
			airFactorCL = airOddCL * aw_f_hiIntensity;

			airOddCR += airFactorCR;
			airEvenCR -= airFactorCR;
			airFactorCR = airOddCR * aw_f_hiIntensity;
		}
		airOddCL = (airOddCL - ((airOddCL - airEvenCL)* aw_inv1)) * aw_inv0;
		airEvenCL = (airEvenCL - ((airEvenCL - airOddCL)* aw_inv1)) * aw_inv0;
		airPrevCL = inputSampleL;
		correctionL = correctionL + airFactorCL;

		airOddCR = (airOddCR - ((airOddCR - airEvenCR)* aw_inv1)) * aw_inv0;
		airEvenCR = (airEvenCR - ((airEvenCR - airOddCR)* aw_inv1)) * aw_inv0;
		airPrevCR = inputSampleR;
		correctionR = correctionR + airFactorCR;

		flop = !flop;
		
		inputSampleL += correctionL;
		inputSampleR += correctionR;
		
		if (aw_f_output < 1.0f) {
			inputSampleL *= aw_f_output;
			inputSampleR *= aw_f_output;
		}
		if (aw_f_wet < 1.0f) {
			inputSampleL = (drySampleL*aw_f_dry)+(inputSampleL*aw_f_wet);
			inputSampleR = (drySampleR*aw_f_dry)+(inputSampleR*aw_f_wet);
		}
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither

		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->airPrevAL = airPrevAL;
    aw_s->airEvenAL = airEvenAL;
    aw_s->airOddAL = airOddAL;
    aw_s->airFactorAL = airFactorAL;
    aw_s->airPrevBL = airPrevBL;
    aw_s->airEvenBL = airEvenBL;
    aw_s->airOddBL = airOddBL;
    aw_s->airFactorBL = airFactorBL;
    aw_s->airPrevCL = airPrevCL;
    aw_s->airEvenCL = airEvenCL;
    aw_s->airOddCL = airOddCL;
    aw_s->airFactorCL = airFactorCL;
    aw_s->tripletPrevL = tripletPrevL;
    aw_s->tripletMidL = tripletMidL;
    aw_s->tripletAL = tripletAL;
    aw_s->tripletBL = tripletBL;
    aw_s->tripletCL = tripletCL;
    aw_s->tripletFactorL = tripletFactorL;
    aw_s->airPrevAR = airPrevAR;
    aw_s->airEvenAR = airEvenAR;
    aw_s->airOddAR = airOddAR;
    aw_s->airFactorAR = airFactorAR;
    aw_s->airPrevBR = airPrevBR;
    aw_s->airEvenBR = airEvenBR;
    aw_s->airOddBR = airOddBR;
    aw_s->airFactorBR = airFactorBR;
    aw_s->airPrevCR = airPrevCR;
    aw_s->airEvenCR = airEvenCR;
    aw_s->airOddCR = airOddCR;
    aw_s->airFactorCR = airFactorCR;
    aw_s->tripletPrevR = tripletPrevR;
    aw_s->tripletMidR = tripletMidR;
    aw_s->tripletAR = tripletAR;
    aw_s->tripletBR = tripletBR;
    aw_s->tripletCR = tripletCR;
    aw_s->tripletFactorR = tripletFactorR;
    aw_s->flipA = flipA;
    aw_s->flipB = flipB;
    aw_s->flop = flop;
    aw_s->count = count;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

static const uint32_t aw_Air_offsets_fast[] = {offsetof(aw_Air_fast_t, A), offsetof(aw_Air_fast_t, B), offsetof(aw_Air_fast_t, C), offsetof(aw_Air_fast_t, D), offsetof(aw_Air_fast_t, E), offsetof(aw_Air_fast_t, F)};
